lab.solution:
def weekly_summary(rows):
    totals = {}
    counts = {}
    missing = 0
    for week, minutes in rows:
        if week is None:
            missing += 1
            continue
        totals[week] = totals.get(week, 0) + minutes
        counts[week] = counts.get(week, 0) + 1
    return totals, counts, missing

assert weekly_summary([('2026-W40', 20), ('2026-W40', 10), (None, 5)]) == ({'2026-W40': 30}, {'2026-W40': 2}, 1)
